// València's storm drains in the detailed city, generated by tools/build-drains.py from the Ajuntament de València's
// Embornals / Imbornales (CC BY 4.0), each turned along its nearest kerb (Cartografia base: Vorades / Bordillos).
// VLD3 (gzipped) = magic, u32 count, u32 byte length of the x column, then columns over the drains in a
// nearest-neighbour walk: x steps, z steps (world, 0.25 m units, zigzag LEB128 varints), u8 kind (0 Valencian kerb
// inlet, 1 small grate, 2 large grate, 3 square, 4 hexagonal), u8 yaw (256ths of a half turn).
export function decodeDrains(data) {
  if (String.fromCharCode(...data.subarray(0, 4)) !== 'VLD3') throw new Error('Invalid drain data.');
  const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
  const count = view.getUint32(4, true);
  let at = 12;
  const steps = () => {
    const out = new Array(count);
    let v = 0, shift = 0, acc = 0;
    for (let i = 0; i < count;) {
      const b = data[at++];
      v += (b & 0x7f) * 2 ** shift;
      if (b & 0x80) { shift += 7; continue; }
      acc += v % 2 === 1 ? -(v + 1) / 2 : v / 2;
      out[i++] = acc;
      v = 0; shift = 0;
    }
    return out;
  };
  const xs = steps(), zs = steps();
  const drains = new Array(count);
  for (let i = 0; i < count; i++) {
    drains[i] = { x: xs[i] / 4, z: zs[i] / 4, kind: data[at + i], yaw: (data[at + count + i] / 256) * Math.PI };
  }
  if (at + count * 2 !== data.length) throw new Error('Drain data is inconsistent.');
  return drains;
}

async function load() {
  try {
    const response = await fetch(new URL('./vlc-drains.bin.gz', import.meta.url));
    if (!response.ok) throw new Error(`Drain data request failed: ${response.status}`);
    const body = new Uint8Array(await response.arrayBuffer());
    const data = body[0] === 0x1f && body[1] === 0x8b
      ? new Uint8Array(await new Response(new Response(body).body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer())
      : body;
    return decodeDrains(data);
  } catch (error) {
    console.error('[drains]', error); // a missing file leaves the streets without drains, not the game stopped
    return [];
  }
}

export const REAL_DRAINS = typeof window === 'undefined' ? [] : await load();
